#!/usr/bin/env python3
"""Render S22 pages and compatibility card from measured JSON. Never promote."""
from html import escape as esc
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]


def render_sources():
    docs = ROOT / 'docs'
    c = json.loads((docs / 's22/run-card.json').read_text())
    audit = json.loads((docs / 'review-20261027/nine-site-audit.json').read_text())
    witness = json.loads((docs / 'review-20261027/witness-audit.json').read_text())
    if (witness['ok_to_submit'] is not False or not witness['s18_alias']['byte_identical']
            or witness['capacity_37654']['overlap_lower_bound'] <= .70
            or any(v['final_verdict'] != 'DUPLICATE' or v['final_dots']['overlap_within_3px'] <= .70
                   for v in witness['existing_candidates'].values())):
        raise ValueError('Review witness evidence does not support the negative portal')
    if c['verdict'] != 'negative' or c['ok_to_submit'] is not False:
        raise ValueError('S22 pages only publish an explicitly negative research result')
    a, h = c['artifact'], c['holdout']
    compat = dict(c)
    compat.update(result='negative', submission_ready=False, verdict=dict(promote=False, OK_TO_SUBMIT='NO'),
                  canonical_evidence='s22/run-card.json', raster_path=a['tif'],
                  raster=dict(path=a['tif'], zip=a['zip'], sha256=c['raster_sha256'], zip_sha256=a['zip_sha256']))
    (docs / 'run-card-S22-OMTJ.json').write_text(json.dumps(compat, indent=2, allow_nan=False) + '\n')
    tif, zip_path = a['tif'].removeprefix('docs/'), a['zip'].removeprefix('docs/')
    dup = c['correlation_overlap_vs_registry']['final_dot_checks']['duplicate']
    ci = f"[{h['ci95'][0]:.6f}, {h['ci95'][1]:.6f}]"
    s18 = witness['existing_candidates']['s18_current']
    status = f'''<section class="hero" data-submission-ready="false">
<div class="eyebrow">GEMSDOE91 / INTEGRITY REVIEW · 27 October 2026</div>
<h1>No file is cleared to submit.</h1>
<p class="lede">The earlier S18 file is byte-identical to a previous TIFF and fails the literal registry check. The previous OMTJ file also fails that check. <strong>No unique competition-ready TIFF was generated in this review.</strong></p>
<div class="status"><strong>OK TO DOWNLOAD: YES — RESEARCH ONLY</strong><strong class="no">OK TO SUBMIT: NO — NOT OK TO SUBMIT</strong></div>
<p><a class="button" download href="{esc(tif)}">Download previous OMTJ research TIFF ↓</a> <a class="button secondary" download href="{esc(zip_path)}">Single-TIFF ZIP</a></p>
<p class="small">These are pre-existing research files, not recommendations. A format pass is not organizer acceptance or authorization to spend a weekly slot. Automated duplicate stop; no human inspection required. <a href="review-20261027/run-card.json">Current review card</a>.</p>
<div class="metrics"><div><span>S18 · 3-pixel overlap</span><b>{s18['final_dots']['overlap_within_3px']:.3%}</b><small>FAIL · required ≤70%</small></div><div><span>OMTJ · 3-pixel overlap</span><b>{dup['overlap_within_3px']:.2%}</b><small>FAIL · same registry witness</small></div><div><span>Local numeric / grid</span><b>PASS</b><small>Not an organizer receipt</small></div><div><span>Experiments / slots this review</span><b>0 / 0</b><small>Stopped before new fit</small></div></div>
<p class="small">Prior OMTJ HOLDOUT-DTI {h['dti']:.6f} · 95% CI {ci} · {esc(h['evaluator_version'])} · {h['withheld_positive_pixels']:,} withheld positives. Catalogue recovery is not a calibrated leaderboard estimate.</p>
<details><summary>OMTJ research-file identity and short note</summary><p><b>Name:</b> <code>{esc(c['submission_name'])}</code></p><p><b>Note ({len(c['submission_note'])}/140):</b> <code>{esc(c['submission_note'])}</code></p><p><b>SHA256:</b> <code>{c['raster_sha256']}</code></p><p>One float32 band; EPSG:32611; 3,730 rows × 3,292 columns; all cells finite and in [0,1]. Local checks do not establish organizer acceptance.</p></details>
</section>'''
    recommendations = {
        'GEMSDOE24': 'Historical dense dotted baseline. Its highest claimed result fails the geometric uniqueness rule; do not re-upload.',
        'GEMSDOE25': 'Support is identical to GEMSDOE30 despite different file bytes. A new name or encoding cannot make it unique.',
        'GEMSDOE27': 'The inherited matrix pairs topo-gap-closure with the top historical site claim; the score-to-file mapping is not independently authenticated. H29 is a separate artifact.',
        'GEMSDOE28': 'The inherited mapping associates h36-1 rung30 with the highest reported value; the user calls it H38. No receipt proves that alias or score-to-file pairing.',
        'GEMSDOE30': 'Same positive support as GEMSDOE25. Educational comparison only; do not resubmit.',
        'GEMSDOE31': 'The inherited solo-d28 reference is strongly shared with the other historical files; its mapping to the user-named h31 identifier lacks an organizer receipt.',
        'GEMSDOE32': 'Highest historical claim in these nine sites. Keep as a research anchor, not a fresh submission; the claimed result has no receipt here.',
        'GEMSDOE33': 'The inherited analog-tip-stepover reference fails the peer-overlap gate; its mapping to the user-named h33-c2 identifier is not receipt-verified.',
        'GEMSDOE36': 'The inherited 38,854-dot Anderson reference overlaps the historical family too strongly. Its mapping to the user-named h40 identifier is not receipt-verified.'}
    rows = []
    sections = []
    for r in sorted(audit['sites'], key=lambda r: -r['claimed_historical_value']):
        peer = r['max_overlap_vs_other_eight']
        rows.append(f'''<tr><th scope="row"><a href="executive-summary.html#{r['site']}">{r['site']}</a></th><td><a href="{esc(r['source_url'])}">{esc(r['filename'])}</a><small>Historical reference only · do not submit</small></td><td>{r['claimed_historical_value']:.4f}<small>USER CLAIM — not ORGANIZER-CONFIRMED</small></td><td>Unavailable<small>No calibrated estimate or receipt</small></td><td class="fail">NO<small>{peer['overlap_within_3px']:.2%} vs {peer['reference_site']} within 3 px</small></td></tr>''')
        sections.append(f'''<article id="{r['site']}"><h3>{r['site']}</h3><p>{esc(recommendations[r['site']])}</p><p class="small">Measured support: {r['positive_pixels']:,} pixels. All cells finite: {r['validator']['all_cells_finite']}. In-footprint finite and grid-match checks: PASS. <a href="{esc(r['blob_api_url'])}">Immutable blob evidence</a> · SHA256 <code>{r['sha256']}</code>.</p></article>''')
    table = f'''<section id="nine-sites"><h2>Which file is best across the nine sites?</h2><p><strong>By your unverified historical claims: GEMSDOE32. By the full submission gates: none is cleared.</strong> This review re-hashed nine historical reference files from the inherited forensic matrix and checked all 72 directed peer comparisons. All nine fail the 70% overlap limit against another site. No historical file is recommended as a new submission.</p><p class="small">Some user identifiers differ from the inherited filenames (including GEMSDOE28, 31, 33 and 36); without an organizer receipt their score-to-file aliases are <strong>unverified</strong>. The table does not establish that a displayed score was earned by the adjacent bytes.</p>
<div class="table-scroll"><table><caption>Historical reference files · repository snapshots: {esc(audit['as_of_utc'][:10])}. Values are user claims, not receipt-bound scores.</caption><thead><tr><th>Site</th><th>Inherited reference file (not an upload recommendation)</th><th>Reported site claim</th><th>Estimated leaderboard score</th><th>Unique among the other eight?</th></tr></thead><tbody>{''.join(rows)}</tbody></table></div>
<p><a href="review-20261027/nine-site-audit.json">Fresh pairwise measurements &amp; SHA256s</a> · <a href="fleet-audit.json">Dated source-inventory feed</a></p></section>'''
    integrity = f'''<section id="integrity"><h2>The duplicate stop, independently reproduced</h2><p>The S18 TIFF advertised as new on 26 October has the <strong>same SHA-256 and identical bytes</strong> as its 25 October predecessor. Its {s18['final_dots']['candidate_dots']:,} dots overlap the registered lattice at {s18['final_dots']['overlap_within_3px']:.3%}; the required maximum is 70%. Its former uniqueness and holdout-pass claims are withdrawn.</p><p><a download href="downloads/gems91-S18-UNIQUE-curvtilt-20000dots-20261026T213155Z-29db2405.tif">Download S18 TIFF for research only</a> · <a href="run-card-S18-UNIQUE.json">Corrected S18 card</a> · <a href="review-20261027/witness-audit.json">Reproduced byte and geometry audit</a></p><p>Only {witness['capacity_37654']['uncovered_pixels']:,} footprint cells are farther than 3 pixels from the registered lattice. At the common {witness['capacity_37654']['candidate_budget']:,}-dot budget, at least {witness['capacity_37654']['minimum_overlapping_dots']:,} dots ({witness['capacity_37654']['overlap_lower_bound']:.2%}) must overlap it. This is a necessary counting bound, not a score. A smaller budget is <em>not ruled out</em> by this bound, but is not automatically unique.</p><p>The restored sample mirror contains positive cells identical to the catalogue, although the official page describes a total-absence sample. Its origin is not independently authenticated; it is used only as a provisional grid reference.</p></section>'''
    research = '''<section id="research"><h2>Why GEMSDOE32 may have the strongest reported result</h2><p>The verified masks show that the 44,090-dot D2.8 reference became a 40,199-dot H27 subset by deleting 3,891 dots within one pixel of the catalogue, then the 37,654-dot R0 subset by deleting a further 2,545 dots between one and two pixels away. No R0 dots were added. Its <b>0.2778 is a user-reported, unverified claim</b>, not an organizer receipt.</p><p>Under the official 300 m triangular-kernel metric, spreading predictions can retain truth coverage while removing redundant false-positive mass; removing low-credit near-catalogue predictions may also help. This is a plausible explanation, not proof of the hidden score's cause. DrivenData confirms the known-fault mask is pixel-exact and that newly labelled faults can be nearby, so broad collars can also remove real discoveries.</p><p>The public leaderboard showed rank 1 at <b>0.4544</b> on 27 October 2026. That official-board observation does not identify a score for this project's TIFFs. Beating 0.2778 is possible in principle, but no reviewed candidate demonstrates it; no defensible leaderboard estimate is available.</p><p><a href="review-20261027/review.md">Evidence, sources and limitations</a> · <a href="review-20261027/hypotheses.md">Four conditional research hypotheses</a> · <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Open the live official leaderboard</a></p></section>'''
    gates = f'''<section id="gates"><h2>Automated gates, without visual inspection</h2><p>These receipts belong to the <strong>previous OMTJ run</strong>, not to S18 or to a new run in this review.</p><ul><li><b>Local format: PASS.</b> TIFF and ZIP re-read against the pinned mirror grid; all pixels finite in [0,1]. Organizer acceptance remains unverified.</li><li><b>Leakage canary: PASS.</b> Seven raw/derived features × four folds; maximum symmetric AUC {c['leakage_canary']['max_symmetric_auc']:.6f} ≤0.90. A canary is not proof of no leakage.</li><li><b>Pre-placement surface:</b> {c['correlation_overlap_vs_registry']['surface_checked']} unique-byte registry rasters checked; max observed absolute Spearman {c['correlation_overlap_vs_registry']['surface_max_rank_correlation']:.6f} ≤0.90. The full registry was not available.</li><li><b>Final dots: FAIL.</b> Stopped at <code>{esc(dup['path'])}</code>, overlap {dup['overlap_within_3px']:.2%}. No dense-raster exception. Remaining final-dot comparisons were not run.</li><li><b>Scientific promotion: NOT ESTABLISHED.</b> No matched incumbent rerun, two frozen references missing and no organizer-complete registry.</li><li><b>Weekly selector: NOT AUTHORIZED.</b> Zero slots spent in this review. Current remaining quota unavailable.</li></ul><p><a href="s22/run-card.json">Canonical JSON run card</a> · <a href="run-card-S22-OMTJ.json">Current-pointer compatibility card</a> · <a href="s22/holdout.json">Holdout and confidence interval</a> · <a href="s22/writer-receipt.json">Validator receipt</a> · <a href="s22/final-dot-checks.json">Duplicate stop witness</a></p></section>'''
    guide = '''<section id="how-to-submit"><h2>Exactly how a future approved submission is entered</h2><p class="warning"><strong>Do not upload the S22 file.</strong> The download above is a negative research deliverable, not an approval to upload that file. These steps apply only to a future file that passes every gate and receives separate selector authorization.</p><ol><li>Run <code>python generate_submission.py --with-data</code> to verify the current downloadable bytes. A format PASS alone is not permission to submit.</li><li>Require complete registry clearance, fold-honest improvement over a matched incumbent, and a current quota/selector record. The official rules specify up to three submissions per week; current remaining allowance must come from the authenticated submission page.</li><li>Download the approved <code>.tif</code>, or its ZIP containing exactly one TIFF. Do not upload this report or a JSON card.</li><li>On DrivenData, choose <b>New submission → File to submit</b>, select the approved raster, and paste its short identifying note into <b>Note (optional)</b>.</li><li>After processing, retain the organizer submission ID, receipt, score, timestamp and exact uploaded SHA256. Only then label that result ORGANIZER-CONFIRMED.</li><li>Before the competition deadline, select one final submission for both rounds. Preserve reproducible code, data licenses and the required generative-AI disclosure.</li></ol><p>The official page says data outside bounds is null/NaN; the research downloads use all-finite zeros outside the sample footprint. This discrepancy and the cause of the reported range rejection remain unresolved; local validation does not establish organizer acceptance.</p><p><a href="https://www.drivendata.org/competitions/306/competition-doe-gems/page/967/#submission-format">Official format</a> · <a href="https://docs.nlr.gov/docs/fy26osti/96647.pdf">Official rules</a> · <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/">Competition</a></p></section>'''
    live_rows = ''.join(
        f'<li data-repository="GEMSDOE{i}"><a href="https://github.com/buffedlizard55-lab/GEMSDOE{i}">GEMSDOE{i}</a> — <span class="commit-status">Loading public commit activity…</span></li>'
        for i in (24, 25, 27, 28, 30, 31, 32, 33, 36)
    )
    live_feed = f'''<section id="source-feed"><h2>Live source activity</h2><p id="live-source-status" role="status" aria-live="polite">Loading public GitHub commit activity. If unavailable, open the repository links.</p><p class="small">Automatically refreshed from the public GitHub API; cached for at most ten minutes per browser tab. This is source activity, not a leaderboard score or readiness decision. For current competition standings, use the official leaderboard link.</p><ul id="live-source-feed">{live_rows}</ul><noscript>JavaScript is disabled. Open the repository links for current activity.</noscript></section>'''
    archive = '''<section id="archive"><h2>Evidence &amp; history</h2><p><a href="s21-pdwc-executive-summary.html">S21 PDWC (historical, negative)</a> · <a href="s20-rhtw-exec-src.html">S20 RHTW (historical)</a> · <a href="archive-results.html">Earlier experiments</a> · <a href="download-audit.html">All-download technical audit</a> · <a href="fleet-audit.json">Dated source inventory</a> · <a href="review-20261027/review.md">Current three-pass review</a> · <a href="s22/review.md">Prior review</a></p><p><a href="REVIEW-ACTIVE-E649E460-20261025.md">Historical safety review</a> · <a href="run-card-E649E460-20261025.json">Historical review card</a> · <a href="s17-lftg.html">S17-LFTG research audit</a> · <a href="s17-cpad.html">S17-CPAD research audit</a></p><p class="small">A source feed is not a score feed. Public leaderboard observed on 27 October: 0.4544 at rank 1, not a receipt for our raster. The link is live; the number is a dated snapshot. <a href="https://www.drivendata.org/competitions/306/competition-doe-gems/leaderboard/">Official leaderboard</a>. Bulk external-data access and authenticated receipts remain limited; current cached inputs were restored automatically and hash-checked.</p></section>'''
    style = '''*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#f3f5f2;color:#1d302b;font:16px/1.65 system-ui,sans-serif}main,header,footer{max-width:1180px;margin:auto;padding:24px}header{display:flex;gap:24px;justify-content:space-between;flex-wrap:wrap;border-bottom:1px solid #d6dfd9}nav{display:flex;gap:22px;flex-wrap:wrap}a{color:#17604a;text-underline-offset:3px}h1{font-size:clamp(32px,5vw,56px);line-height:1.1;letter-spacing:-2px;margin:20px 0}h2{font-size:27px;line-height:1.3}h3{font-size:21px}section{background:white;border:1px solid #d6dfd9;border-radius:12px;padding:30px;margin-bottom:24px}.hero{border-top:5px solid #b97428}.eyebrow,span{font-size:12px;letter-spacing:.08em;text-transform:uppercase;color:#526a61}.lede{max-width:850px;font-size:19px}.status{display:flex;gap:15px;flex-wrap:wrap;font-size:13px}.status strong{background:#e6efe9;border-radius:4px;padding:8px 12px}.status .no,.warning{background:#fff1df;color:#7f4312}.button{display:inline-block;background:#194d3e;color:white;text-decoration:none;padding:12px 18px;border-radius:6px;font-weight:650;margin:5px 8px 5px 0}.secondary{background:#e8eeea;color:#194d3e}.metrics{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:18px;margin:28px 0}.metrics div{border-left:2px solid #d6dfd9;padding:0 14px}.metrics b{display:block;font-size:29px}.small,small{font-size:13px;color:#526a61}small{display:block}.table-scroll{overflow:auto}table{border-collapse:collapse;width:100%;font-size:13px}caption{text-align:left;padding:14px 0;color:#526a61}th,td{text-align:left;vertical-align:top;border-bottom:1px solid #dde4df;padding:14px 12px}thead{background:#eef3ef}td:nth-child(2){min-width:220px;max-width:370px;overflow-wrap:anywhere}.fail{color:#923e19;font-weight:700}code{overflow-wrap:anywhere;font-size:12px}details{border-top:1px solid #d6dfd9;padding-top:14px}summary{cursor:pointer;font-weight:600}article{border-top:1px solid #d6dfd9;padding:10px 0}li{margin:10px 0}.warning{padding:15px;border-radius:6px}footer{font-size:13px;color:#526a61}@media(max-width:600px){main,header,footer{padding:16px}section{padding:20px}th,td{padding:10px 8px}}'''
    def shell(title, body):
        return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} · GEMSDOE91</title><script defer src="assets/live-source-feed.js"></script><style>{style}</style></head><body><header><b>GEMS / RESEARCH OPERATIONS</b><nav aria-label="Main navigation"><a href="index.html">Download &amp; status</a><a href="executive-summary.html">Executive summary</a><a href="executive-summary.html#how-to-submit">Submission guide</a></nav></header><main id="main">{body}</main><footer>Maximize P(Win) · Own the Outcome · Negative results protect scarce submission slots.</footer></body></html>\n'''
    (docs / 's22-index-src.html').write_text(shell('Integrity review and automated verdict', status + integrity + table + research + gates + live_feed + archive))
    (docs / 's22-exec-src.html').write_text(shell('Nine-site executive summary and submission guide', status + integrity + table + '<section><h2>Executive summary for every site</h2>' + ''.join(sections) + '</section>' + research + gates + guide + live_feed + archive))
    # Dedicated names survive later changes to the current front door.
    (docs / 's22-executive-summary.html').write_text((docs / 's22-exec-src.html').read_text())
    from scripts.render_s18_review import render as render_s18_review
    render_s18_review()


if __name__ == '__main__':
    render_sources()
